import pytest

from calc import divide, percent


class TestDivide:
    """Tests for the divide function."""

    def test_divide_basic(self):
        """Basic division returns correct result."""
        assert divide(10, 2) == 5

    def test_divide_floats(self):
        """Division with floats."""
        assert divide(7, 2) == 3.5

    def test_divide_by_one(self):
        """Dividing by one returns the numerator."""
        assert divide(5, 1) == 5

    def test_divide_zero_numerator(self):
        """Zero divided by a number returns zero."""
        assert divide(0, 5) == 0

    def test_divide_negative_numerator(self):
        """Division with negative numerator."""
        assert divide(-10, 2) == -5

    def test_divide_negative_denominator(self):
        """Division with negative denominator."""
        assert divide(10, -2) == -5

    def test_divide_both_negative(self):
        """Division with both negative returns positive."""
        assert divide(-10, -2) == 5

    def test_divide_by_zero_raises(self):
        """Dividing by zero raises ValueError."""
        with pytest.raises(ValueError, match="cannot divide by zero"):
            divide(10, 0)


class TestPercent:
    """Tests for the percent function."""

    def test_percent_basic(self):
        """Basic percentage calculation."""
        assert percent(25, 100) == 25.0

    def test_percent_half(self):
        """Half of something is 50 percent."""
        assert percent(50, 100) == 50.0

    def test_percent_quarter(self):
        """Quarter is 25 percent."""
        assert percent(25, 100) == 25.0

    def test_percent_zero_part(self):
        """Zero as part returns zero percent."""
        assert percent(0, 100) == 0.0

    def test_percent_one_third(self):
        """One third is approximately 33.33 percent."""
        result = percent(1, 3)
        assert abs(result - 33.333333) < 0.001

    def test_percent_greater_than_100(self):
        """Part can be greater than whole (>100%)."""
        assert percent(150, 100) == 150.0

    def test_percent_by_zero_raises(self):
        """Percent with zero whole raises ValueError."""
        with pytest.raises(ValueError, match="cannot divide by zero"):
            percent(50, 0)

import pytest

from metrics import mean


class TestMean:
    """Tests for the mean function."""

    def test_mean_basic(self):
        """Mean of simple integers."""
        assert mean([1, 2, 3]) == 2.0

    def test_mean_single_value(self):
        """Mean of a single value is that value."""
        assert mean([5]) == 5.0

    def test_mean_two_values(self):
        """Mean of two values."""
        assert mean([10, 20]) == 15.0

    def test_mean_floats(self):
        """Mean with float values."""
        assert mean([1.5, 2.5, 3.0]) == pytest.approx(2.333333, abs=0.001)

    def test_mean_negative_numbers(self):
        """Mean with negative numbers."""
        assert mean([-1, -2, -3]) == -2.0

    def test_mean_mixed_positive_negative(self):
        """Mean with mixed positive and negative."""
        assert mean([-5, 0, 5]) == 0.0

    def test_mean_large_numbers(self):
        """Mean with large numbers."""
        assert mean([1000, 2000, 3000]) == 2000.0

    def test_mean_zero(self):
        """Mean of all zeros."""
        assert mean([0, 0, 0]) == 0.0

    def test_mean_empty_raises(self):
        """Mean of empty list raises ValueError."""
        with pytest.raises(ValueError, match="no values"):
            mean([])

